/**
 * User Controller — Profile, addresses, order history.
 * Generated by BackendForge
 */
const { parsePagination, paginatedResponse } = require('../utils/pagination');
const { ApiError } = require('../middleware/error-handler.middleware');
const { User, Order, OrderItem, Address } = require('../models');

const userController = {
  /**
   * GET /api/users/profile — Get own profile
   */
  async getProfile(req, res, next) {
    try {
      const user = await User.findByPk(req.userId, {
        include: [{ model: Address, as: 'addresses' }],
      });
      if (!user) throw ApiError.notFound('User not found');
      res.json({ success: true, data: { user } });
    } catch (error) { next(error); }
  },

  /**
   * PUT /api/users/profile — Update profile (name, phone, avatar)
   * Phone number is saved when the user clicks save.
   */
  async updateProfile(req, res, next) {
    try {
      const { name, phone, avatar } = req.body;
      const updates = {};
      if (name !== undefined) updates.name = name;
      if (phone !== undefined) updates.phone = phone; // Phone number save
      if (avatar !== undefined) updates.avatar = avatar;

      await User.update(updates, { where: { id: req.userId } });
      const user = await User.findByPk(req.userId);

      res.json({
        success: true,
        message: 'Profile updated successfully',
        data: { user },
      });
    } catch (error) { next(error); }
  },

  /**
   * GET /api/users/addresses
   */
  async getAddresses(req, res, next) {
    try {
      const addresses = await Address.findAll({ where: { userId: req.userId }, order: [['isDefault', 'DESC']] });
      res.json({ success: true, data: { addresses } });
    } catch (error) { next(error); }
  },

  /**
   * POST /api/users/addresses
   */
  async addAddress(req, res, next) {
    try {
      if (req.body.isDefault) {
        await Address.update({ isDefault: false }, { where: { userId: req.userId } });
      }
      const address = await Address.create({ ...req.body, userId: req.userId });
      res.status(201).json({ success: true, message: 'Address added', data: { address } });
    } catch (error) { next(error); }
  },

  /**
   * PUT /api/users/addresses/:addressId
   */
  async updateAddress(req, res, next) {
    try {
      const address = await Address.findOne({ where: { id: req.params.addressId, userId: req.userId } });
      if (!address) throw ApiError.notFound('Address not found');
      if (req.body.isDefault) {
        await Address.update({ isDefault: false }, { where: { userId: req.userId } });
      }
      await address.update(req.body);
      res.json({ success: true, message: 'Address updated', data: { address } });
    } catch (error) { next(error); }
  },

  /**
   * DELETE /api/users/addresses/:addressId
   */
  async deleteAddress(req, res, next) {
    try {
      await Address.destroy({ where: { id: req.params.addressId, userId: req.userId } });
      res.json({ success: true, message: 'Address deleted' });
    } catch (error) { next(error); }
  },

  /**
   * GET /api/users/orders — Customer's own order history with live status.
   * This shows the SAME data that admin updates — no sync needed.
   */
  async getMyOrders(req, res, next) {
    try {
      const pagination = parsePagination(req.query);

      const { count: total, rows: orders } = await Order.findAndCountAll({
        where: { userId: req.userId },
        include: [{ model: OrderItem, as: 'items' }],
        order: [['createdAt', 'DESC']],
        offset: pagination.offset,
        limit: pagination.limit,
      });

      res.json({ success: true, ...paginatedResponse(orders, total, pagination) });
    } catch (error) { next(error); }
  },
};

module.exports = userController;
